"""Make a slug: the ASCII a-z and 0-9 characters of a text, joined by a separator, such as "hello-world"."""
import re
import unicodedata

_WORD = re.compile(r"[a-z0-9]+")


def slugify(text, sep="-"):
    """Slug of text, with accents dropped and letters lower-cased. Raises ValueError if nothing is left."""
    ascii_text = unicodedata.normalize("NFKD", text).encode("ascii", "ignore").decode("ascii")
    words = _WORD.findall(ascii_text.lower())
    if not words:
        raise ValueError(f"nothing left to make a slug from: {text!r}")
    return sep.join(words)
import contextlib
import io
import unittest

from textkit.cli import main
from textkit.slug import slugify


def run(*argv):
    out, err = io.StringIO(), io.StringIO()
    with contextlib.redirect_stdout(out), contextlib.redirect_stderr(err):
        code = main(list(argv))
    return code, out.getvalue(), err.getvalue()


class SlugifyTest(unittest.TestCase):
    def test_examples(self):
        self.assertEqual(slugify("Héllo, Wörld!"), "hello-world")
        self.assertEqual(slugify("  C++ & Rust  "), "c-rust")
        self.assertEqual(slugify("a b", sep="_"), "a_b")

    def test_accents_are_dropped_to_base_letters(self):
        self.assertEqual(slugify("café crème"), "cafe-creme")

    def test_lower_cases(self):
        self.assertEqual(slugify("ABC Def"), "abc-def")

    def test_runs_of_other_characters_become_one_sep(self):
        self.assertEqual(slugify("a --- b...c"), "a-b-c")
        self.assertEqual(slugify("a \t\n b"), "a-b")

    def test_no_leading_or_trailing_sep(self):
        self.assertEqual(slugify("--x--"), "x")
        self.assertEqual(slugify("__x__", sep="_"), "x")

    def test_digits_are_kept(self):
        self.assertEqual(slugify("Version 2.0 beta"), "version-2-0-beta")

    def test_custom_sep(self):
        self.assertEqual(slugify("a b c", sep="__"), "a__b__c")

    def test_non_latin_letters_are_dropped(self):
        self.assertEqual(slugify("日本 abc"), "abc")

    def test_nothing_left_raises(self):
        for text in ("!!!", "", "   ", "日本語"):
            with self.subTest(text=text):
                with self.assertRaises(ValueError):
                    slugify(text)
        with self.assertRaises(ValueError):
            slugify("!!!", sep="_")

    def test_accented_letter_alone_is_kept(self):
        self.assertEqual(slugify("é!"), "e")


class SlugCommandTest(unittest.TestCase):
    def test_default_sep(self):
        self.assertEqual(run("slug", "Héllo, Wörld!"), (0, "hello-world\n", ""))

    def test_sep_option(self):
        self.assertEqual(run("slug", "a b", "--sep", "_"), (0, "a_b\n", ""))

    def test_nothing_left_exits_2(self):
        code, out, err = run("slug", "!!!")
        self.assertEqual(code, 2)
        self.assertEqual(out, "")
        self.assertTrue(err.startswith("error:"))

    def test_listed_in_commands(self):
        code, out, _ = run("commands")
        self.assertEqual(code, 0)
        self.assertIn("slug", out.split())


if __name__ == "__main__":
    unittest.main()
