        self.assertEqual(top_words("don't stop", 5), [("don", 1), ("stop", 1), ("t", 1)])
        self.assertEqual(top_words("a1b2c, a-b", 5), [("a", 2), ("b", 2), ("c", 1)])

    def test_sorts_by_count_then_alphabetically(self):
        self.assertEqual(top_words("b a b c a b", 3), [("b", 3), ("a", 2), ("c", 1)])
        self.assertEqual(top_words("z y x", 3), [("x", 1), ("y", 1), ("z", 1)])

    def test_k_limits_result(self):
        self.assertEqual(top_words("b a b c a b", 2), [("b", 3), ("a", 2)])

    def test_fewer_distinct_words_returns_all(self):
        self.assertEqual(top_words("hi hi", 10), [("hi", 2)])
        self.assertEqual(top_words("", 3), [])
        self.assertEqual(top_words("123 !!!", 3), [])

    def test_k_below_one_raises(self):
        for k in (0, -1):
            with self.subTest(k=k):
                with self.assertRaises(ValueError):
                    top_words("a b", k)


class TopCommandTest(unittest.TestCase):
